// MARK: - Trace context from the caller

/// The operation tests live beside the helper tests because the propagator hook is
/// process-wide state: one serialized suite keeps the two from racing.
extension TraceContextUtilTests {
  /// The caller's ambient scope: a task-local the tracing hook reads. The hook is
  /// process-wide state, so these tests run one at a time and restore it.
  private enum CallerScope {
    @TaskLocal static var span: String?
  }

  /// An authenticator whose credential lookup suspends before it answers.
  private final class SlowAuth: BaseAuthenticator, @unchecked Sendable {
    override func host() -> String { return "" }
    override func authHeaders() async -> [String: String] {
      try? await Task.sleep(nanoseconds: 20_000_000)
      return [:]
    }
  }

  private static let traceSpanA = "00-4bf92f3577b34da6a3ce929d0e0e4736-00f067aa0ba902b7-01"
  private static let traceSpanB = "00-0af7651916cd43dd8448eb211c80319c-b7ad6b7169203331-01"

  private static func installCallerScopeHook() {
    TraceContextUtil.propagator = { headers in
      if let span = CallerScope.span {
        headers["traceparent"] = span
      }
    }
  }

  /// Runs one operation under the given span and returns the headers it sent.
  private func call(under span: String?, authenticator: Authenticator? = nil) async throws
    -> [String: String]
  {
    let mockClient = BaseApiTests.MockApiClient()
    mockClient.responseBody = "{\"name\":\"test\",\"photoUrls\":[]}"
    let config = ConfigurationBuilder().baseURL("https://example.com").build()
    let api = PetApi(apiClient: mockClient, config: config, authenticator: authenticator)
    _ = try await CallerScope.$span.withValue(span) {
      try await api.addPet(pet: Pet(name: "test", photoUrls: []))
    }
    return mockClient.lastHeaders
  }

  @Test func testBhvTracing013OperationSendsTheTraceparentOfTheCallerSpan() async throws {
    Self.installCallerScopeHook()
    defer { TraceContextUtil.propagator = nil }
    let headers = try await call(under: Self.traceSpanA)
    #expect(headers["traceparent"] == Self.traceSpanA)
  }

  @Test func testBhvTracing014SpanReachesTraceparentWhenBuildingHeadersWaitsOnCredentials()
    async throws
  {
    Self.installCallerScopeHook()
    defer { TraceContextUtil.propagator = nil }
    let headers = try await call(under: Self.traceSpanA, authenticator: SlowAuth())
    #expect(headers["traceparent"] == Self.traceSpanA)
  }

  @Test func testBhvTracing015ConcurrentOperationsEachSendTheirOwnCallerSpan() async throws {
    Self.installCallerScopeHook()
    defer { TraceContextUtil.propagator = nil }
    async let first = call(under: Self.traceSpanA, authenticator: SlowAuth())
    async let second = call(under: Self.traceSpanB, authenticator: SlowAuth())
    let (firstHeaders, secondHeaders) = try await (first, second)
    #expect(firstHeaders["traceparent"] == Self.traceSpanA)
    #expect(secondHeaders["traceparent"] == Self.traceSpanB)
  }

  @Test func testBhvTracing016OperationWithNoActiveSpanSendsNoTraceparent() async throws {
    Self.installCallerScopeHook()
    defer { TraceContextUtil.propagator = nil }
    let traced = try await call(under: Self.traceSpanA)
    #expect(traced["traceparent"] == Self.traceSpanA)
    let untraced = try await call(under: nil)
    #expect(untraced["traceparent"] == nil)
  }

  // MARK: - Pagination

  private struct PagedReply: Sendable {
    var status = 200
    var body = "{}"
    var headers: [String] = []
    var delayMillis = 0

    static func ok(_ body: String, _ headers: String...) -> PagedReply {
      return PagedReply(body: body, headers: headers)
    }

    static func failed(_ status: Int, _ body: String = "{}", _ headers: String...) -> PagedReply {
      return PagedReply(status: status, body: body, headers: headers)
    }

    func after(_ millis: Int) -> PagedReply {
      var copy = self
      copy.delayMillis = millis
      return copy
    }
  }

  /// One request a paged server received: the path, the query parameters and the lower-cased headers.
  private struct PagedRequest: Sendable {
    let path: String
    let query: [String: String]
    let headers: [String: String]

    init(head: String) {
      let lines = head.components(separatedBy: "\r\n")
      let target = lines.first?.split(separator: " ").dropFirst().first.map(String.init) ?? "/"
      let parts = URLComponents(string: "http://host" + target)
      path = parts?.path ?? target
      var found: [String: String] = [:]
      for item in parts?.queryItems ?? [] { found[item.name] = item.value ?? "" }
      query = found
      var seenHeaders: [String: String] = [:]
      for line in lines.dropFirst() {
        guard let colon = line.firstIndex(of: ":") else { continue }
        let name = line[..<colon].lowercased()
        seenHeaders[name] = line[line.index(after: colon)...].trimmingCharacters(in: .whitespaces)
      }
      headers = seenHeaders
    }

    func param(_ name: String) -> String? { query[name] }
  }

  private func pagedServer(
    _ answer: @escaping @Sendable (PagedRequest, Int) -> PagedReply
  ) throws -> RawServer {
    return try RawServer { connection, hit, head in
      let reply = answer(PagedRequest(head: head), hit)
      if reply.delayMillis > 0 { Thread.sleep(forTimeInterval: Double(reply.delayMillis) / 1000) }
      let bytes = Data(reply.body.utf8)
      var text = "HTTP/1.1 \(reply.status) Test\r\nContent-Type: application/json\r\n"
      for header in reply.headers { text += header + "\r\n" }
      text += "Content-Length: \(bytes.count)\r\nConnection: close\r\n\r\n"
      connection.send(Data(text.utf8) + bytes)
    }
  }

  private func pagedPet(_ name: String) -> String {
    return "{\"id\":1,\"name\":\"\(name)\",\"photoUrls\":[]}"
  }

  /// A catalog page: the pets of page `page` of `size`, and the cursor of the page after it.
  private func catalogBody(_ page: Int, _ size: Int, _ pages: Int) -> String {
    let items = (0..<size).map { pagedPet("p\(page)-\($0)") }.joined(separator: ",")
    let next = page + 1 < pages ? ",\"next_cursor\":\"c\(page + 1)\"" : ""
    return "{\"items\":[\(items)]\(next)}"
  }

  /// A catalog of `pages` pages of `size` pets; the cursor of page n is "c" and n.
  private func catalogServer(_ pages: Int, _ size: Int) throws -> RawServer {
    return try pagedServer { request, _ in
      let page = request.param("cursor").flatMap { Int($0.dropFirst()) } ?? 0
      return .ok(self.catalogBody(page, size, pages))
    }
  }

  /// A feed of `pages` pages of one pet each; every page but the last names the next one in a Link header.
  private func feedServer(_ pages: Int) throws -> RawServer {
    let origin = LockedValue<String>("")
    let server = try pagedServer { request, _ in
      let index = request.param("page").flatMap { Int($0) } ?? 0
      let link =
        "</pet/feed?page=\(index)>; rel=\"prev\", <\(origin.get())/pet/feed?page=\(index + 1)&secret=s3>; title=\"a, b\"; rel=\"next\""
      return index + 1 < pages
        ? .ok("[\(self.pagedPet("f\(index)"))]", "Link: \(link)")
        : .ok("[\(self.pagedPet("f\(index)"))]")
    }
    origin.set(server.origin)
    return server
  }

  /// Five pets in total, served two at a time from the offset the request names.
  private func offsetServer() throws -> RawServer {
    return try pagedServer { request, _ in
      let from = request.param("offset").flatMap { Int($0) } ?? 0
      return .ok("{\"items\":[\(self.petsJSON(min(from, 5), min(from + 2, 5)))]}")
    }
  }

  /// Five pets in total, two to a numbered page, from page 1.
  private func pageNumberServer() throws -> RawServer {
    return try pagedServer { request, _ in
      let index = request.param("page").flatMap { Int($0) } ?? 1
      let from = (index - 1) * 2
      return .ok(
        "{\"items\":[\(self.petsJSON(min(from, 5), min(from + 2, 5)))],\"has_more\":true}")
    }
  }

  /// Five pets in total, two to a page, each page with the id of its last pet and a has_more flag.
  private func afterServer() throws -> RawServer {
    return try pagedServer { request, _ in
      let from = request.param("starting_after").flatMap { Int($0.dropFirst()) }.map { $0 + 1 } ?? 0
      let to = min(from + 2, 5)
      return .ok(
        "{\"data\":[\(self.petsJSON(from, to))],\"has_more\":\(to < 5),\"last_id\":\"p\(to - 1)\"}")
    }
  }

  /// Three pets, one to a page, each page with the URL of the next one in its body.
  private func nextUrlServer(_ pages: Int) throws -> RawServer {
    let origin = LockedValue<String>("")
    let server = try pagedServer { request, _ in
      let index = request.param("p").flatMap { Int($0) } ?? 0
      let next =
        index + 1 < pages
        ? ",\"next_url\":\"\(origin.get())/pet/next?p=\(index + 1)\"" : ""
      return .ok("{\"items\":[\(self.pagedPet("f\(index)"))]\(next)}")
    }
    origin.set(server.origin)
    return server
  }

  /// The pets p(from) up to p(to - 1), as JSON objects separated by commas.
  private func petsJSON(_ from: Int, _ to: Int) -> String {
    return (from..<max(from, to)).map { self.pagedPet("p\($0)") }.joined(separator: ",")
  }

  private func pagedPetApi(
    _ server: RawServer, maxRetries: Int = 0, headers: [String: String] = [:],
    authenticator: Authenticator? = nil
  ) throws -> PetApi {
    var config = ConfigurationBuilder().baseURL(server.origin)
    for (name, value) in headers { config = config.defaultHeader(name: name, value: value) }
    let transport = try TransportOptionsBuilder().maxRetries(maxRetries).build()
    return PetApi(
      apiClient: try DefaultApiClient(transportOptions: transport), config: config.build(),
      authenticator: authenticator)
  }

  private func names<S: AsyncSequence>(_ pets: S) async throws -> [String] where S.Element == Pet {
    var found: [String] = []
    for try await pet in pets { found.append(pet.name) }
    return found
  }

  private func paramsSeen(_ server: RawServer, _ name: String) -> [String?] {
    return server.heads.map { PagedRequest(head: $0).param(name) }
  }

  /// An authenticator whose header differs on every call.
  private final class CountingAuth: BaseAuthenticator, @unchecked Sendable {
    private let lock = NSLock()
    private var calls = 0

    override func host() -> String { return "" }
    override func authHeaders() async -> [String: String] {
      let number: Int = lock.withLock {
        calls += 1
        return calls
      }
      return ["Authorization": "Bearer n\(number)"]
    }
  }

  private func apiSource(_ file: String) throws -> String {
    return try String(
      contentsOf: URL(fileURLWithPath: FileManager.default.currentDirectoryPath)
        .appendingPathComponent("Sources/PetstoreClient/Api/\(file)"),
      encoding: .utf8)
  }

  /* A paged operation reads no page until the first item or page is requested. */
  @Test func testBhvPagination001APagedOperationReadsNoPageUntilTheFirstItemOrPageIsRequested()
    async throws
  {
    let server = try catalogServer(2, 2)
    defer { server.stop() }
    let paginator = try pagedPetApi(server).listPetCatalogPages()
    #expect(server.hits == 0, "the method sends nothing")
    let items = paginator.items()
    let pages = paginator.pages()
    #expect(server.hits == 0, "getting a view sends nothing")
    var itemIterator = items.makeAsyncIterator()
    #expect(try await itemIterator.next() != nil)
    #expect(server.hits == 1, "the first read sends the first request")
    var pageIterator = pages.makeAsyncIterator()
    #expect(try await pageIterator.next() != nil)
  }

