  /* The per-call timeout, headers and retry count apply to each page request. */
  @Test func testBhvPagination017ThePerCallTimeoutHeadersAndRetryCountApplyToEachPageRequest()
    async throws
  {
    let server = try pagedServer { _, number in
      number % 2 == 1
        ? .failed(503, "{}", "Retry-After: 0") : .ok(self.catalogBody(number == 2 ? 0 : 1, 1, 2))
    }
    defer { server.stop() }
    _ = try await names(
      try pagedPetApi(server, maxRetries: 5).listPetCatalogPages(
        options: ListPetCatalogOptions(headers: ["X-Trace": "t1"], maxRetries: 1)
      ).items())
    #expect(server.hits == 4, "each page was tried twice: one try and one retry")
    for head in server.heads { #expect(PagedRequest(head: head).headers["x-trace"] == "t1") }

    /* The per-call timeout reaches the transport on every page request, and a timeout on the
     * second page is raised from the read that needed it, as a network timeout error. */
    PagedStubProtocol.reset()
    let configuration = URLSessionConfiguration.ephemeral
    configuration.protocolClasses = [PagedStubProtocol.self]
    let session = URLSession(configuration: configuration)
    let transport = try TransportOptionsBuilder().session(session).maxRetries(0).build()
    let api = PetApi(
      apiClient: try DefaultApiClient(transportOptions: transport),
      config: ConfigurationBuilder().baseURL("http://paged.test").build())
    var items = api.listPetCatalogPages(options: ListPetCatalogOptions(timeout: 7000)).items()
      .makeAsyncIterator()
    #expect(try await items.next()?.name == "p0-0")
    await #expect(throws: NetworkTimeoutError.self) { _ = try await items.next() }
    #expect(
      PagedStubProtocol.timeouts() == [7.0, 7.0], "the timeout was set on both page requests")
  }

