  /* Cancelling mid-iteration aborts the in-flight page request and is not reported as a timeout. */
  @Test
  func
    testBhvPagination019CancellingMidIterationAbortsTheInFlightPageRequestAndIsNotReportedAsATimeout()
    async throws
  {
    let server = try RawServer { connection, hit, head in
      if hit == 1 {
        let body = Data(self.catalogBody(0, 1, 2).utf8)
        connection.send(
          Data(
            "HTTP/1.1 200 Test\r\nContent-Type: application/json\r\nContent-Length: \(body.count)\r\nConnection: close\r\n\r\n"
              .utf8) + body)
      } else {
        connection.server.awaitRelease()
      }
    }
    defer { server.stop() }
    let paginator = try pagedPetApi(server).listPetCatalogPages(
      options: ListPetCatalogOptions(timeout: 20_000))
    let call = Task { () -> Error? in
      do {
        for try await _ in paginator {}
        return nil
      } catch {
        return error
      }
    }
    let deadline = Date().addingTimeInterval(10)
    while server.hits < 2 && Date() < deadline { try await Task.sleep(nanoseconds: 20_000_000) }
    #expect(server.hits == 2, "the second page request is in flight")
    let started = Date()
    call.cancel()
    let error = await call.value
    #expect(error is CancellationError, "got \(String(describing: error))")
    #expect(!(error is NetworkTimeoutError))
    #expect(Date().timeIntervalSince(started) < 5)
  }

