/// A URL protocol that answers the first page of the catalog and times out the second, and keeps the timeout of each request.
private final class PagedStubProtocol: URLProtocol {
  nonisolated(unsafe) private static var seen: [TimeInterval] = []
  private static let lock = NSLock()

  static func reset() { lock.withLock { seen = [] } }
  static func timeouts() -> [TimeInterval] { lock.withLock { seen } }

  override class func canInit(with request: URLRequest) -> Bool { return true }
  override class func canonicalRequest(for request: URLRequest) -> URLRequest { return request }

  override func startLoading() {
    let number: Int = PagedStubProtocol.lock.withLock {
      PagedStubProtocol.seen.append(request.timeoutInterval)
      return PagedStubProtocol.seen.count
    }
    if number > 1 {
      client?.urlProtocol(self, didFailWithError: URLError(.timedOut))
      return
    }
    let body = Data(
      "{\"items\":[{\"id\":1,\"name\":\"p0-0\",\"photoUrls\":[]}],\"next_cursor\":\"c1\"}".utf8)
    if let url = request.url,
      let response = HTTPURLResponse(
        url: url, statusCode: 200, httpVersion: "HTTP/1.1",
        headerFields: ["Content-Type": "application/json"])
    {
      client?.urlProtocol(self, didReceive: response, cacheStoragePolicy: .notAllowed)
      client?.urlProtocol(self, didLoad: body)
    }
    client?.urlProtocolDidFinishLoading(self)
  }

  override func stopLoading() {}
}

/// A client whose transport always fails before a response arrives.
private final class FailingApiClient: ApiClient, @unchecked Sendable {
  func sendRequest(method: String, url: String, headers: [String: String], body: Any?)
    async throws -> ApiHttpResponse
  {
    try await sendRequest(
      method: method, url: url, headers: headers, body: body, noRedirect: false)
  }

  func sendRequest(
    method: String, url: String, headers: [String: String], body: Any?, noRedirect: Bool
  )
    async throws -> ApiHttpResponse
  {
    throw NetworkError(statusCode: 0, message: "connection reset")
  }
}

